//! Independent polynomial camera observations, never generated by the fitted camera model.
use ftx_core::{Mat3, Vec2, Vec3};
use ftx_measure::{
    photo::intrinsics::{CalibrationInput, Control, Corner, DistortionFit, View, calibrate_camera},
    triangulate::{FrameId, Partition},
};
use serde_json::json;

fn fixture() -> CalibrationInput {
    let controls: Vec<_> = (0..48)
        .map(|i| Control {
            id: format!("p{i:02}"),
            sheet_xz_m: Vec2::new((i % 8) as f64 * 0.06 - 0.21, (i / 8) as f64 * 0.06 - 0.15),
        })
        .collect();
    let base = Mat3::from_rows([[1., 0., 0.], [0., 0., -1.], [0., 1., 0.]]);
    let views = [
        (0.35, 0.12, -0.18, -0.10, 0.80),
        (-0.45, 0.3, 0.16, 0.13, 0.75),
        (0.2, -0.55, -0.12, 0.18, 0.85),
        (-0.3, -0.25, 0.23, -0.14, 0.8),
        (0.5, -0.4, 0.03, -0.04, 0.66),
        (-0.2, 0.5, -0.24, 0.06, 0.9),
    ]
    .iter()
    .enumerate()
    .map(|(i, &(a, b, tx, ty, tz))| {
        let r = Mat3::rotation(Vec3::new(1., 0., 0.), a)
            * Mat3::rotation(Vec3::new(0., 1., 0.), b)
            * base;
        let t = Vec3::new(tx, ty, tz);
        View {
            frame: FrameId {
                stream: "synthetic-brown".into(),
                timestamp_us: i as u64 * 100000,
            },
            partition: if i == 5 {
                Partition::HeldOut
            } else {
                Partition::Fit
            },
            corners: controls
                .iter()
                .enumerate()
                .map(|(i, p)| {
                    let q = r.mul_vec(Vec3::new(p.sheet_xz_m.x, 0., p.sheet_xz_m.y)) + t;
                    let (x, y) = (q.x / q.z, q.y / q.z);
                    let r2 = x * x + y * y;
                    let radial = 1.0 + 0.12 * r2 - 0.035 * r2 * r2 + 0.009 * r2 * r2 * r2;
                    let xd = x * radial + 2.0 * 0.002 * x * y - 0.0015 * (r2 + 2.0 * x * x);
                    let yd = y * radial + 0.002 * (r2 + 2.0 * y * y) - 2.0 * 0.0015 * x * y;
                    Corner {
                        id: p.id.clone(),
                        pixel_px: Vec2::new(1050. * xd + 790., 1000. * yd + 610.),
                        partition: if [0, 7, 40, 47].contains(&i) {
                            Partition::HeldOut
                        } else {
                            Partition::Fit
                        },
                    }
                })
                .collect(),
        }
    })
    .collect();
    CalibrationInput {
        schema: "ftx-camera-calibration-input/1".into(),
        image_model: "brown5_zero_skew".into(),
        lens_id: "synthetic-brown".into(),
        pinhole_evidence: String::new(),
        distortion_fit: Some(DistortionFit {
            model_evidence: "Independent synthetic Brown lens; not a camera calibration".into(),
            max_radius: 0.9,
            max_iterations: 80,
            corner_noise: None,
        }),
        reference_evidence: "Synthetic 60 mm planar grid".into(),
        image_size_px: [1600, 1200],
        rotation_cw_deg: 0,
        controls,
        views,
    }
}

#[test]
fn jointly_recovers_focals_principal_point_and_all_five_distortion_coefficients() {
    let input = fixture();
    let report = calibrate_camera(&input).unwrap();
    assert_eq!(report.status, "ACCEPTED", "{report:#?}");
    let k = report.solution.as_ref().unwrap().intrinsics;
    assert!(
        (k.focal_px - Vec2::new(1050., 1000.)).norm() < 1e-5,
        "{k:?}"
    );
    assert!(
        (k.principal_px - Vec2::new(790., 610.)).norm() < 1e-5,
        "{k:?}"
    );
    for (a, b) in k.distortion.radial.iter().zip([0.12, -0.035, 0.009]) {
        assert!((a - b).abs() < 1e-6, "{k:?}");
    }
    for (a, b) in k.distortion.tangential.iter().zip([0.002, -0.0015]) {
        assert!((a - b).abs() < 1e-7, "{k:?}");
    }
    assert_eq!(k.distortion.max_radius, 0.9);
    k.validate().unwrap();
    assert!(
        report
            .checks
            .iter()
            .flat_map(|v| &v.corners)
            .all(|c| c.error_px.unwrap() < 1e-6)
    );
    let diagnostics = report.refinement.as_ref().unwrap();
    assert!(
        diagnostics
            .objective_history
            .windows(2)
            .all(|w| w[1] < w[0])
    );
    assert_eq!(diagnostics.termination, "gradient_converged");
    assert!(diagnostics.fit_radius_range.unwrap()[1] < 0.9);
    // This scene genuinely needs more than a raw-pixel pinhole fit.
    let mut pinhole = input;
    pinhole.image_model = "pinhole_zero_skew".into();
    pinhole.pinhole_evidence =
        "Deliberately incorrect pinhole assumption in a negative test".into();
    pinhole.distortion_fit = None;
    assert!(calibrate_camera(&pinhole).unwrap().solution.is_none());
}

#[test]
fn held_out_pixels_cannot_steer_the_lens_or_joint_convergence() {
    let input = fixture();
    let good = calibrate_camera(&input).unwrap();
    assert!(good.solution.is_some());
    for held_view in [false, true] {
        let mut bad = input.clone();
        let i = if held_view { 5 } else { 0 };
        bad.views[i].corners[0].pixel_px.x += 25.;
        let report = calibrate_camera(&bad).unwrap();
        assert_eq!(report.status, "REJECTED", "{report:#?}");
        assert!(report.solution.is_none());
        assert_eq!(json!(good.refinement), json!(report.refinement));
        for (a, b) in good.checks[1..5].iter().zip(&report.checks[1..5]) {
            assert_eq!(json!(a), json!(b));
        }
    }
    // Fit points from a held-out view may change only that view's pose fit, never the lens.
    let mut changed = input;
    changed.views[5].corners[3].pixel_px.x += 25.;
    let bad = calibrate_camera(&changed).unwrap();
    assert!(bad.solution.is_none());
    assert_eq!(json!(good.refinement), json!(bad.refinement));
}

#[test]
fn ordering_and_metric_reference_similarity_do_not_change_the_lens() {
    let input = fixture();
    let good = calibrate_camera(&input).unwrap();
    let mut reordered = input.clone();
    reordered.views.reverse();
    reordered.controls.reverse();
    for v in &mut reordered.views {
        v.corners.reverse();
    }
    assert_eq!(json!(good), json!(calibrate_camera(&reordered).unwrap()));
    let mut scaled = input;
    for p in &mut scaled.controls {
        p.sheet_xz_m = p.sheet_xz_m * 0.1 + Vec2::new(2., -3.);
    }
    let other = calibrate_camera(&scaled).unwrap();
    assert!(other.solution.is_some(), "{other:#?}");
    let a = good.solution.unwrap().intrinsics;
    let b = other.solution.unwrap().intrinsics;
    assert!((a.focal_px - b.focal_px).norm() < 1e-5);
    assert!((a.principal_px - b.principal_px).norm() < 1e-5);
}

#[test]
fn sparse_views_budget_stop_and_invalid_models_never_publish_calibration() {
    let input = fixture();
    let mut short = input.clone();
    short.views.truncate(4);
    assert!(calibrate_camera(&short).unwrap().solution.is_none());
    let mut short = input.clone();
    short.distortion_fit.as_mut().unwrap().max_iterations = 1;
    let report = calibrate_camera(&short).unwrap();
    assert!(report.solution.is_none());
    assert!(
        report.flags.iter().any(|s| s.contains("BUDGET_STOP")),
        "{report:#?}"
    );
    for (model, radius) in [("pinhole_zero_skew", 0.9), ("brown5_zero_skew", -1.)] {
        let mut bad = input.clone();
        bad.image_model = model.into();
        bad.distortion_fit.as_mut().unwrap().max_radius = radius;
        assert!(calibrate_camera(&bad).is_err());
    }
    let mut narrow = input;
    narrow.distortion_fit.as_mut().unwrap().max_radius = 0.01;
    assert!(calibrate_camera(&narrow).unwrap().solution.is_none());
}

#[test]
fn noisy_corners_report_their_residuals_instead_of_being_trimmed() {
    let mut input = fixture();
    for (i, v) in input.views.iter_mut().enumerate() {
        for (j, p) in v.corners.iter_mut().enumerate() {
            p.pixel_px.x += 0.05 * ((i * 17 + j * 13) % 11) as f64 - 0.25;
            p.pixel_px.y += 0.04 * ((i * 23 + j * 7) % 13) as f64 - 0.24;
        }
    }
    let report = calibrate_camera(&input).unwrap();
    assert_eq!(report.status, "ACCEPTED", "{report:#?}");
    assert_eq!(
        report.checks.iter().map(|v| v.corners.len()).sum::<usize>(),
        288
    );
    let d = report.refinement.as_ref().unwrap();
    assert!(d.objective_history.last().unwrap() > &0.01);
    assert!(d.objective_history.windows(2).all(|w| w[1] < w[0]));
    assert!(
        (report.solution.as_ref().unwrap().intrinsics.focal_px - Vec2::new(1050., 1000.)).norm()
            < 10.
    );
}

fn inline_noise(input: &mut CalibrationInput, sigma_px: f64) {
    input.distortion_fit.as_mut().unwrap().corner_noise =
        Some(ftx_measure::photo::intrinsics::CornerNoise {
            model: "independent_isotropic".into(),
            sigma_px,
            evidence:
                "Synthetic independent per-coordinate perturbations, not residual-derived sigma"
                    .into(),
        });
}

#[test]
fn covariance_is_opt_in_and_scales_with_declared_noise_not_residual_rms() {
    let mut input = fixture();
    let original = json!(calibrate_camera(&input).unwrap());
    assert!(original.get("uncertainty").is_none());
    assert!(
        original["input"]["distortion_fit"]
            .get("corner_noise")
            .is_none()
    );
    inline_noise(&mut input, 0.2);
    let a = calibrate_camera(&input).unwrap();
    inline_noise(&mut input, 0.4);
    let b = calibrate_camera(&input).unwrap();
    assert_eq!(json!(a.solution), original["solution"]);
    assert_eq!(json!(a.refinement), original["refinement"]);
    assert_eq!(json!(a.solution), json!(b.solution));
    let (a, b) = (a.uncertainty.unwrap(), b.uncertainty.unwrap());
    assert_eq!(a.fit_corners, 220);
    assert_eq!(a.nuisance_parameters, 30);
    assert_eq!(a.residual_degrees_of_freedom, 401);
    for i in 0..9 {
        assert!(a.standard_deviations[i] > 0.0);
        assert_eq!(b.standard_deviations[i], 2.0 * a.standard_deviations[i]);
        for j in 0..9 {
            assert_eq!(a.covariance[i][j], a.covariance[j][i]);
            assert_eq!(b.covariance[i][j], 4.0 * a.covariance[i][j]);
        }
    }
    assert!(
        a.covariance[4][5].abs() > 1e-12,
        "coefficient correlation is retained"
    );
}

#[test]
fn covariance_never_uses_held_out_observations_and_failed_fits_publish_none() {
    let mut input = fixture();
    inline_noise(&mut input, 0.1);
    let good = calibrate_camera(&input).unwrap();
    let mut changed = input.clone();
    changed.views[5].corners[0].pixel_px.x += 0.2;
    changed.views[0].corners[0].pixel_px.y += 0.2;
    let other = calibrate_camera(&changed).unwrap();
    assert_eq!(other.status, "ACCEPTED");
    assert_eq!(json!(good.uncertainty), json!(other.uncertainty));
    changed.views[5].corners[0].pixel_px.x += 30.0;
    let rejected = calibrate_camera(&changed).unwrap();
    assert!(rejected.solution.is_none() && rejected.uncertainty.is_none());
    assert_eq!(json!(good.refinement), json!(rejected.refinement));
    input.distortion_fit.as_mut().unwrap().max_iterations = 1;
    let rejected = calibrate_camera(&input).unwrap();
    assert!(rejected.solution.is_none() && rejected.uncertainty.is_none());
}

#[test]
fn noise_requires_finite_positive_sigma_and_an_explicit_supported_model() {
    for sigma in [0.0, -1.0, f64::INFINITY, f64::NAN, 1001.0] {
        let mut input = fixture();
        inline_noise(&mut input, sigma);
        assert!(calibrate_camera(&input).is_err());
    }
    for (model, evidence) in [
        ("correlated", "known sigma"),
        ("independent_isotropic", "  "),
    ] {
        let mut input = fixture();
        inline_noise(&mut input, 0.25);
        let n = input
            .distortion_fit
            .as_mut()
            .unwrap()
            .corner_noise
            .as_mut()
            .unwrap();
        n.model = model.into();
        n.evidence = evidence.into();
        assert!(calibrate_camera(&input).is_err());
    }
}

fn coefficients(k: ftx_measure::camera::Intrinsics) -> [f64; 9] {
    [
        k.focal_px.x,
        k.focal_px.y,
        k.principal_px.x,
        k.principal_px.y,
        k.distortion.radial[0],
        k.distortion.radial[1],
        k.distortion.radial[2],
        k.distortion.tangential[0],
        k.distortion.tangential[1],
    ]
}

#[test]
fn covariance_matches_independent_small_noise_refits() {
    // Independent Rademacher noise has the declared variance; Gaussianity is not needed for
    // the first-order covariance identity. No fitted values are used as ground truth.
    let mut input = fixture();
    inline_noise(&mut input, 0.005);
    let reference = calibrate_camera(&input).unwrap().uncertainty.unwrap();
    let mut state = 173_u64;
    let mut sign = || {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        if state & 1 == 0 { -1.0 } else { 1.0 }
    };
    let mut draws = Vec::new();
    for _ in 0..80 {
        let mut trial = input.clone();
        trial.distortion_fit.as_mut().unwrap().corner_noise = None;
        for v in trial
            .views
            .iter_mut()
            .filter(|v| v.partition == Partition::Fit)
        {
            for c in v
                .corners
                .iter_mut()
                .filter(|p| p.partition == Partition::Fit)
            {
                c.pixel_px.x += 0.005 * sign();
                c.pixel_px.y += 0.005 * sign();
            }
        }
        let report = calibrate_camera(&trial).unwrap();
        assert_eq!(
            report.status,
            "ACCEPTED",
            "{:?} / {:?}",
            report.checks.last().map(|c| &c.failure),
            report.refinement
        );
        draws.push(coefficients(report.solution.unwrap().intrinsics));
    }
    for i in 0..9 {
        let mean = draws.iter().map(|d| d[i]).sum::<f64>() / draws.len() as f64;
        let empirical =
            draws.iter().map(|d| (d[i] - mean).powi(2)).sum::<f64>() / (draws.len() - 1) as f64;
        let ratio = empirical / reference.covariance[i][i];
        assert!(
            (0.5..1.65).contains(&ratio),
            "parameter {i}: variance ratio {ratio}"
        );
    }
}
fn noise(sigma_px: f64) -> ftx_measure::photo::intrinsics::uncertainty::CalibrationNoise {
    ftx_measure::photo::intrinsics::uncertainty::CalibrationNoise {
        schema: "ftx-calibration-corner-noise/1".into(),
        sigma_px,
        evidence: "Synthetic known per-axis pixel noise".into(),
        independence_evidence: "Independent synthetic draws across axes, corners and images".into(),
    }
}

#[test]
fn covariance_is_nonzero_at_perfect_fit_scales_with_noise_and_preserves_geometry() {
    use ftx_measure::photo::intrinsics::uncertainty::calibrate_camera_with_uncertainty;
    let input = fixture();
    let plain = calibrate_camera(&input).unwrap();
    let a = calibrate_camera_with_uncertainty(&input, &noise(0.25)).unwrap();
    let b = calibrate_camera_with_uncertainty(&input, &noise(0.5)).unwrap();
    assert_eq!(json!(plain.solution), json!(a.solution));
    assert_eq!(json!(plain.refinement), json!(a.refinement));
    let ua = a.conditional_uncertainty.as_ref().unwrap();
    assert_eq!(ua.status, "AVAILABLE", "{ua:?}");
    let ca = ua.estimate.as_ref().unwrap();
    let cb = b
        .conditional_uncertainty
        .as_ref()
        .unwrap()
        .estimate
        .as_ref()
        .unwrap();
    for i in 0..9 {
        assert!(ca.sigma()[i] > 0.0 && ca.sigma()[i].is_finite());
        for j in 0..9 {
            assert_eq!(ca.covariance()[i][j], ca.covariance()[j][i]);
            assert_eq!(4.0 * ca.covariance()[i][j], cb.covariance()[i][j]);
        }
    }
    assert!(ca.covariance()[0][1].abs() > 0.01);
    let mut reordered = input.clone();
    reordered.controls.reverse();
    reordered.views.reverse();
    for view in &mut reordered.views {
        view.corners.reverse();
    }
    let reordered = calibrate_camera_with_uncertainty(&reordered, &noise(0.25)).unwrap();
    assert_eq!(json!(a), json!(reordered));
    let mut changed = input;
    for v in &mut changed.views {
        for p in &mut v.corners {
            if v.partition == Partition::HeldOut || p.partition == Partition::HeldOut {
                p.pixel_px.x += 0.1;
            }
        }
    }
    let changed = calibrate_camera_with_uncertainty(&changed, &noise(0.25)).unwrap();
    assert!(changed.solution.is_some(), "{changed:#?}");
    assert_eq!(
        json!(a.conditional_uncertainty),
        json!(changed.conditional_uncertainty)
    );
}

#[test]
fn unavailable_or_undeclared_uncertainty_is_never_zero_precision() {
    use ftx_measure::photo::intrinsics::uncertainty::calibrate_camera_with_uncertainty;
    for sigma in [0.0, -1.0, f64::NAN, f64::INFINITY, 1001.] {
        assert!(calibrate_camera_with_uncertainty(&fixture(), &noise(sigma)).is_err());
    }
    let mut missing = noise(0.5);
    missing.independence_evidence.clear();
    assert!(calibrate_camera_with_uncertainty(&fixture(), &missing).is_err());
    let mut failed = fixture();
    failed.views[5].corners[0].pixel_px.x += 25.;
    let report = calibrate_camera_with_uncertainty(&failed, &noise(0.5)).unwrap();
    assert!(report.solution.is_none());
    let uncertainty = report.conditional_uncertainty.unwrap();
    assert_eq!(uncertainty.status, "UNAVAILABLE");
    assert!(uncertainty.estimate.is_none());
    let mut pinhole = fixture();
    pinhole.image_model = "pinhole_zero_skew".into();
    pinhole.distortion_fit = None;
    assert!(calibrate_camera_with_uncertainty(&pinhole, &noise(0.5)).is_err());
    assert!(
        json!(calibrate_camera(&fixture()).unwrap())
            .get("conditional_uncertainty")
            .is_none()
    );
}

#[test]
fn marginal_covariance_matches_independent_pixel_differences_and_svd_inverse() {
    use ftx_measure::photo::intrinsics::uncertainty::calibrate_camera_with_uncertainty;
    // This test assembles the full 39-column Jacobian independently in *physical* lens units
    // and camera-centre metres, unlike refinement's log-focal/normalized-sheet coordinates.
    let report = calibrate_camera_with_uncertainty(&fixture(), &noise(0.4)).unwrap();
    let input = &report.input;
    let sol = report.solution.as_ref().unwrap();
    let k = sol.intrinsics;
    let parameters = [
        k.focal_px.x,
        k.focal_px.y,
        k.principal_px.x,
        k.principal_px.y,
        k.distortion.radial[0],
        k.distortion.radial[1],
        k.distortion.radial[2],
        k.distortion.tangential[0],
        k.distortion.tangential[1],
    ];
    let project = |v: [f64; 9], q: Vec3| {
        let (x, y) = (q.x / q.z, q.y / q.z);
        let r2 = x * x + y * y;
        let radial = 1. + v[4] * r2 + v[5] * r2 * r2 + v[6] * r2 * r2 * r2;
        [
            v[0] * (x * radial + 2. * v[7] * x * y + v[8] * (r2 + 2. * x * x)) + v[2],
            v[1] * (y * radial + v[7] * (r2 + 2. * y * y) + 2. * v[8] * x * y) + v[3],
        ]
    };
    let mut rows = Vec::<[f64; 39]>::new();
    for (vi, view) in input
        .views
        .iter()
        .filter(|v| v.partition == Partition::Fit)
        .enumerate()
    {
        let c = sol
            .sheet_poses
            .iter()
            .find(|p| p.frame == view.frame)
            .unwrap()
            .camera_in_sheet_frame;
        for corner in view
            .corners
            .iter()
            .filter(|p| p.partition == Partition::Fit)
        {
            let p = input
                .controls
                .iter()
                .find(|p| p.id == corner.id)
                .unwrap()
                .sheet_xz_m;
            let world = Vec3::new(p.x, 0., p.y);
            let mut jac = [[0.; 39]; 2];
            for col in 0..15 {
                let h = if col < 4 { 1e-3 } else { 1e-6 };
                let evaluate = |step: f64| {
                    let mut v = parameters;
                    let mut rotation = c.world_to_camera;
                    let mut center = c.center_m;
                    if col < 9 {
                        v[col] += step;
                    } else {
                        let axis = match (col - 9) % 3 {
                            0 => Vec3::new(1., 0., 0.),
                            1 => Vec3::new(0., 1., 0.),
                            _ => Vec3::new(0., 0., 1.),
                        };
                        if col < 12 {
                            rotation = Mat3::rotation(axis, step) * rotation;
                        } else {
                            center += axis * step;
                        }
                    }
                    project(v, rotation.mul_vec(world - center))
                };
                let a = evaluate(h);
                let b = evaluate(-h);
                let index = if col < 9 { col } else { 9 + 6 * vi + col - 9 };
                for r in 0..2 {
                    jac[r][index] = (a[r] - b[r]) / (2. * h);
                }
            }
            rows.extend(jac);
        }
    }
    let norm: [f64; 39] =
        std::array::from_fn(|i| rows.iter().map(|r| r[i] * r[i]).sum::<f64>().sqrt());
    let normal: [[f64; 39]; 39] = std::array::from_fn(|i| {
        std::array::from_fn(|j| {
            rows.iter()
                .map(|r| (r[i] / norm[i]) * (r[j] / norm[j]))
                .sum()
        })
    });
    let estimate = report
        .conditional_uncertainty
        .as_ref()
        .unwrap()
        .estimate
        .as_ref()
        .unwrap();
    for i in 0..9 {
        let mut unit = [0.; 39];
        unit[i] = 1.;
        let column = ftx_core::linalg::lstsq(&normal, &unit);
        for j in 0..9 {
            let want = column[j] * 0.16 / (norm[i] * norm[j]);
            let scale = estimate.sigma()[i] * estimate.sigma()[j];
            assert!(
                (estimate.covariance()[i][j] - want).abs() < 1e-4 * scale,
                "{i},{j}: {want} vs {}",
                estimate.covariance()[i][j]
            );
        }
    }
}
